      const __m512d t30 = _mm512_add_pd(t27, t29);
      const __m512d t31 = _mm512_add_pd(t25, t30);
      const __m512d t32 = _mm512_sub_pd(v0, t15);
      const __m512d t33 = _mm512_sub_pd(t27, t29);
      const __m512d t34 = _mm512_add_pd(t32, t33);
      const __m512d t35 = _mm512_sub_pd(v1, t24);
      const __m512d t36 = _mm512_sub_pd(t18, t20);
      const __m512d t37 = _mm512_sub_pd(t35, t36);
      const __m512d t38 = _mm512_sub_pd(t16, t21);
      const __m512d t39 = _mm512_sub_pd(t25, t30);
      const __m512d t40 = _mm512_sub_pd(t32, t33);
      const __m512d t41 = _mm512_add_pd(t35, t36);
      _mm512_mask_storeu_pd(out + 2 * (o + 0 * ns), m0, lf8_ilo(t22, t31));
      _mm512_mask_storeu_pd(out + 2 * (o + 0 * ns) + 8, m1, lf8_ihi(t22, t31));
      _mm512_mask_storeu_pd(out + 2 * (o + 1 * ns), m0, lf8_ilo(t34, t37));
      _mm512_mask_storeu_pd(out + 2 * (o + 1 * ns) + 8, m1, lf8_ihi(t34, t37));
      _mm512_mask_storeu_pd(out + 2 * (o + 2 * ns), m0, lf8_ilo(t38, t39));
      _mm512_mask_storeu_pd(out + 2 * (o + 2 * ns) + 8, m1, lf8_ihi(t38, t39));
      _mm512_mask_storeu_pd(out + 2 * (o + 3 * ns), m0, lf8_ilo(t40, t41));
      _mm512_mask_storeu_pd(out + 2 * (o + 3 * ns) + 8, m1, lf8_ihi(t40, t41));
