static void lf_small_n2_b(const double *in, double *out) {
  const double v0 = in[0];
  const double v1 = in[1];
  const double v2 = in[2];
  const double v3 = in[3];
  const double t4 = v0 + v2;
  const double t5 = v1 + v3;
  const double t6 = v0 - v2;
  const double t7 = v1 - v3;
  out[0] = t4;
  out[1] = t5;
  out[2] = t6;
  out[3] = t7;
}

